class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.8.0/commando_0.8.0_darwin_arm64.tar.gz"
      sha256 "37cac854dc37ed1d45fe9f936e309fad8990279cb2ea5b683443011046af8888"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.8.0/commando_0.8.0_darwin_amd64.tar.gz"
      sha256 "9ec67130e14ce8d3b865a24779c83284585497a356beddc49158aa381a61ddf4"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.8.0/commando_0.8.0_linux_arm64.tar.gz"
      sha256 "ab28cace53893b1883fee49f1a5c2e48aac65fb930177b18f7f3ce0b4dda9589"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.8.0/commando_0.8.0_linux_amd64.tar.gz"
      sha256 "d44e3c0a4a66474a8ec6186d660f9f8192635de6b34b5973c25f1a81d6303a9c"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
